grant create on schema api,app_private to git_tutor_commands;
create function api.authorize_credit_conversion(p_source_credit_id uuid,p_package_purchase_id uuid,p_credit_quanta bigint,p_carrying_value_minor bigint,p_grant_policy_version_id uuid,p_expires_at timestamptz,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();source finance_private.customer_credit_lots%rowtype;purchase app_private.package_purchases%rowtype;policy app_private.package_grant_policy_versions%rowtype;intent app_private.credit_conversion_intents%rowtype;context jsonb;scope jsonb;hash text;source_version integer;begin
 select * into source from finance_private.customer_credit_lots where id=p_source_credit_id;
 if source.id is null then raise exception 'NOT_FOUND';end if;if source.payer_account_id<>actor then raise exception 'FORBIDDEN';end if;
 select * into purchase from app_private.package_purchases where id=p_package_purchase_id;if purchase.id is null then raise exception 'NOT_FOUND';end if;perform app_private.package_assert_scope(actor,purchase.learner_id,'payments');
 context:=app_private.booking_begin(actor,'authorize_credit_conversion',jsonb_build_object('source_credit_id',p_source_credit_id,'package_purchase_id',p_package_purchase_id,'credit_quanta',p_credit_quanta,'carrying_value_minor',p_carrying_value_minor,'grant_policy_version_id',p_grant_policy_version_id,'expires_at',p_expires_at,'expected_version',p_expected_version),p_idempotency_key);
 if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 scope:=finance_private.finance_discover_scope(array[purchase.charge_id],array[source.transfer_id],'{}','{}');perform app_private.booking_lock_financial_scope(scope);
 select version into source_version from finance_private.credit_lot_accounts where credit_lot_id=source.id;if source_version is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;
 select * into purchase from app_private.package_purchases where id=purchase.id;perform app_private.package_assert_scope(actor,purchase.learner_id,'payments');
 if purchase.purchase_state='cancelled' then raise exception 'STATE_CONFLICT';end if;
 if p_credit_quanta is null or p_credit_quanta not between 1 and 9007199254740991 or p_carrying_value_minor is null or p_carrying_value_minor not between 1 and 9007199254740991 then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
 if p_expires_at is null or not isfinite(p_expires_at) or p_expires_at<=now() or p_expires_at>now()+interval '24 hours' then raise exception 'INVALID_TIME';end if;
 select * into policy from app_private.package_grant_policy_versions where id=p_grant_policy_version_id;
 if policy.id is null or policy.status<>'approved' or policy.effective_at>now() or policy.content->>'valuation_rule'<>'reviewed_exact_source_credit' or policy.content->>'currency'<>source.currency or not(policy.content->'eligible_package_contract_version_ids' @> jsonb_build_array(purchase.contract_version_id)) then raise exception 'POLICY_INCOMPLETE';end if;
 if p_credit_quanta>(policy.content->>'maximum_credit_quanta_per_grant')::bigint or p_carrying_value_minor>(policy.content->>'maximum_carrying_value_minor_per_grant')::bigint then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
 if not exists(select 1 from finance_private.incoming_transfers where id=source.transfer_id and state='settled' and current_payer_binding_id=source.payer_binding_id) then raise exception 'TRANSFER_UNSETTLED';end if;
 if finance_private.finance_transfer_balance(source.transfer_id)->>'reconciliation_state'<>'clear' or finance_private.finance_credit_available(source.id)<p_carrying_value_minor or(finance_private.finance_transfer_balance(source.transfer_id)->>'available_minor')::bigint<p_carrying_value_minor then raise exception 'INSUFFICIENT_FUNDS';end if;
 hash:=app_private.catalog_hash(jsonb_build_object('source_credit_id',source.id,'payer_binding_id',source.payer_binding_id,'payer_account_id',actor,'source_version',source_version,'package_purchase_id',purchase.id,'learner_id',purchase.learner_id,'contract_terms_hash',purchase.contract_hash,'credit_quanta',p_credit_quanta,'carrying_value_minor',p_carrying_value_minor,'currency',source.currency,'grant_policy_version_id',policy.id,'expires_at',p_expires_at));
 insert into app_private.credit_conversion_intents(source_credit_id,payer_binding_id,payer_account_id,learner_id,package_purchase_id,contract_terms_hash,credit_quanta,carrying_value_minor,grant_policy_version_id,expires_at,intent_hash,command_id) values(source.id,source.payer_binding_id,actor,purchase.learner_id,purchase.id,purchase.contract_hash,p_credit_quanta,p_carrying_value_minor,policy.id,p_expires_at,hash,(context->>'command_id')::uuid) returning * into intent;
 perform set_config('response.status','201',true);
 return app_private.booking_finish(context,intent.id,intent.version,jsonb_build_object('credit_conversion_intent_id',intent.id,'intent_hash',hash,'state','authorized','expires_at',p_expires_at),'credit_conversion_authorized',jsonb_build_object('credit_conversion_intent_id',intent.id,'package_purchase_id',purchase.id));
end $$;
create function app_private.payment_credit_intent_dto(p_intent_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('credit_conversion_intent_id',id,'version',version,'source_credit_id',source_credit_id,'package_purchase_id',package_purchase_id,'credit_quanta',credit_quanta,'carrying_value_minor',carrying_value_minor,'currency','EGP','grant_policy_version_id',grant_policy_version_id,'intent_hash',intent_hash,'expires_at',expires_at,'state',case when state='authorized' and expires_at<=now() then 'expired' else state end,'accepted_at',accepted_at) from app_private.credit_conversion_intents where id=p_intent_id$$;
create function api.get_credit_conversion_intent(p_credit_conversion_intent_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();intent app_private.credit_conversion_intents%rowtype;begin select * into intent from app_private.credit_conversion_intents where id=p_credit_conversion_intent_id;if intent.id is null then raise exception 'NOT_FOUND';end if;if not app_private.has_role(actor,'admin') then if intent.payer_account_id<>actor then raise exception 'NOT_FOUND';end if;perform app_private.package_assert_scope(actor,intent.learner_id,'payments');end if;return app_private.payment_credit_intent_dto(intent.id);end $$;
create function api.list_credit_conversion_intents(p_package_purchase_id uuid default null,p_state text default null,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;is_admin boolean:=app_private.has_role(actor,'admin');begin
 if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('authorized','consumed','expired','invalidated')) then raise exception 'VALIDATION_ERROR';end if;
 if p_package_purchase_id is not null then perform app_private.package_assert_scope(actor,(select learner_id from app_private.package_purchases where id=p_package_purchase_id),'payments',true);end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_credit_intent_dto(x.id)) order by x.created_at desc,x.id desc),'[]') into rows from(select i.* from app_private.credit_conversion_intents i where(is_admin or(i.payer_account_id=actor and (exists(select 1 from app_private.learners current_learner where current_learner.id=i.learner_id and current_learner.account_id=actor) or exists(select 1 from app_private.guardian_links current_link where current_link.learner_id=i.learner_id and current_link.guardian_account_id=actor and current_link.revoked_at is null and current_link.valid_from<=now() and current_link.valid_until>now() and 'payments'=any(current_link.scopes))))) and(p_package_purchase_id is null or i.package_purchase_id=p_package_purchase_id) and(p_state is null or case when i.state='authorized' and i.expires_at<=now() then 'expired' else i.state end=p_state) and(p_cursor is null or(i.created_at,i.id)<(after_at,after_id)) order by i.created_at desc,i.id desc limit p_limit+1)x;
 return app_private.package_page(rows,p_limit);
end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname='payment_credit_intent_dto') or(n.nspname='api' and p.proname in('authorize_credit_conversion','get_credit_conversion_intent','list_credit_conversion_intents')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private from git_tutor_commands;
notify pgrst,'reload schema';

